package com.hudhud.app.domain.model

/**
 * Represents a smart suggestion generated by the AI engine.
 * Used for column detection, template matching, and variable linking.
 */
data class SmartSuggestion(
    val id: String,
    val type: SuggestionType,
    val title: String,
    val description: String,
    val confidence: Float, // 0.0 to 1.0
    val action: SuggestionAction,
    val metadata: Map<String, Any> = emptyMap(),
    val isAutoApplied: Boolean = false, // Whether this suggestion was auto-applied
) {
    /**
     * Get confidence as percentage string
     */
    val confidencePercent: String
        get() = "${(confidence * 100).toInt()}%"

    /**
     * Check if this is a high confidence suggestion
     */
    val isHighConfidence: Boolean
        get() = confidence >= 0.8f

    /**
     * Check if this is a medium confidence suggestion
     */
    val isMediumConfidence: Boolean
        get() = confidence in 0.5f..0.79f
}

/**
 * Types of smart suggestions
 */
enum class SuggestionType {
    COLUMN_PHONE,      // Suggested phone column
    COLUMN_TEXT,       // Suggested text/message column
    COLUMN_NAME,       // Suggested name column
    COLUMN_AMOUNT,     // Suggested amount column
    COLUMN_DATE,       // Suggested date column
    TEMPLATE_MATCH,    // Suggested template for file
    VARIABLE_LINK,     // Suggested variable to column link
    VALUE_MISSING,     // Missing value warning
    VALUE_SUGGESTION,  // Suggested value for missing data
    PHONE_INVALID,     // Invalid phone number warning
    MESSAGE_LONG,      // Message too long warning
    MESSAGE_DUPLICATE, // Duplicate message warning
    BATCH_WARNING,     // Batch size warning
    RATE_LIMIT,        // Rate limit warning
}

/**
 * Actions that can be taken on a suggestion
 */
enum class SuggestionAction {
    SELECT_COLUMN,     // Select this column for mapping
    APPLY_TEMPLATE,    // Apply this template
    LINK_VARIABLE,     // Link variable to column
    USE_VALUE,         // Use suggested value
    FIX_PHONE,         // Fix phone number
    EXCLUDE_ROW,       // Exclude row from processing
    CONTINUE,          // Continue with current selection
    CANCEL,            // Cancel current operation
    IGNORE,            // Ignore this suggestion
}

/**
 * Result of smart analysis
 */
data class SmartAnalysisResult(
    val suggestions: List<SmartSuggestion>,
    val warnings: List<SmartSuggestion>,
    val statistics: AnalysisStatistics,
    val isComplete: Boolean = true,
    val error: String? = null,
) {
    /**
     * Get all high confidence suggestions
     */
    val highConfidenceSuggestions: List<SmartSuggestion>
        get() = suggestions.filter { it.isHighConfidence }

    /**
     * Get all warnings
     */
    val allWarnings: List<SmartSuggestion>
        get() = warnings

    /**
     * Check if there are any critical issues
     */
    val hasCriticalIssues: Boolean
        get() = statistics.errorCount > 0 || warnings.any { it.confidence < 0.3f }

    /**
     * Get success rate
     */
    val successRate: Float
        get() = if (statistics.totalCount > 0) {
            (statistics.totalCount - statistics.errorCount).toFloat() / statistics.totalCount
        } else 0f
}

/**
 * Statistics from analysis
 */
data class AnalysisStatistics(
    val totalCount: Int = 0,
    val validCount: Int = 0,
    val errorCount: Int = 0,
    val warningCount: Int = 0,
    val missingValueCount: Int = 0,
    val invalidPhoneCount: Int = 0,
    val duplicateCount: Int = 0,
    val longMessageCount: Int = 0,
    val emptyMessages: Int = 0,
)

/**
 * Result of template matching
 */
data class TemplateMatchResult(
    val template: SavedTemplate,
    val score: Float,
    val matchedVariables: List<VariableMatch>,
    val missingVariables: List<String>,
    val isMatch: Boolean,
) {
    /**
     * Get match percentage
     */
    val matchPercent: String
        get() = "${(score * 100).toInt()}%"
}

/**
 * Variable match information
 */
data class VariableMatch(
    val templateVariable: String,
    val fileColumn: String?,
    val confidence: Float,
    val isMatched: Boolean,
)

/**
 * Result of column mapping
 */
data class MappingResult(
    val phoneColumn: String?,
    val variableMappings: Map<String, String>, // variable -> column
    val confidence: Float,
    val isComplete: Boolean,
    val suggestions: List<SmartSuggestion>,
)